import { motion } from 'framer-motion';
import { X, Filter } from 'lucide-react';
import { useParams, Link } from 'react-router-dom';

import ArticleGrid from '../components/Articles/ArticleGrid';
import LoadingSpinner from '../components/common/LoadingSpinner';
import ProjectGrid from '../components/Projects/ProjectGrid';
import SEO from '../components/SEO';
import { useFilteredContent } from '../hooks/useFilteredContent';
import { denormalizeTag } from '../utils/tagUtils';

export default function FilteredResultsPage() {
  const { tag } = useParams<{ tag: string }>();
  const { articles, projects, isLoading } = useFilteredContent(tag ? [tag] : []);

  const displayTag = tag ? denormalizeTag(tag) : '';
  const totalResults = (articles?.length || 0) + (projects?.length || 0);

  const title = tag ? `${displayTag} Results | REWI.RE` : 'All Results | REWI.RE';
  const description = tag
    ? `Explore ${totalResults} results tagged with ${displayTag} at REWI.RE`
    : 'Browse all projects and articles at REWI.RE';

  if (isLoading) {
    return (
      <div className="min-h-screen pt-24">
        <div className="container mx-auto px-6">
          <LoadingSpinner />
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen pt-24 pb-16 bg-gray-50 dark:bg-neutral-darker">
      <SEO
        title={title}
        description={description}
        path={tag ? `/filtered/${tag}` : '/filtered'}
        type="website"
      />

      <div className="container mx-auto px-6">
        <div className="mb-12">
          <div className="flex items-center justify-between mb-6">
            <div className="flex items-center gap-3">
              <Filter className="w-8 h-8 text-primary dark:text-primary-light" />
              <h1 className="text-3xl font-bold text-neutral-dark dark:text-white">
                {tag ? `Results for "${displayTag}"` : 'All Results'}
              </h1>
            </div>
            {tag && (
              <Link
                to="/filtered"
                className="inline-flex items-center gap-2 px-4 py-2 bg-gray-100 dark:bg-neutral-dark rounded-full hover:bg-gray-200 dark:hover:bg-gray-800 transition-colors"
              >
                <span className="text-sm text-neutral-dark/70 dark:text-white/70">
                  Clear filter
                </span>
                <X className="w-4 h-4" />
              </Link>
            )}
          </div>
          <p className="text-lg text-neutral-dark/70 dark:text-white/70">
            Found {totalResults} {totalResults === 1 ? 'result' : 'results'}
            {tag && (
              <span className="opacity-75">
                {' '}
                tagged with{' '}
                <span className="font-medium text-primary dark:text-primary-light">
                  {displayTag}
                </span>
              </span>
            )}
          </p>
        </div>

        {projects.length > 0 && (
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            className="mb-16"
          >
            <h2 className="text-2xl font-bold text-neutral-dark dark:text-white mb-8">
              Projects{' '}
              {projects.length > 0 && (
                <span className="text-lg font-normal text-neutral-dark/70 dark:text-white/70">
                  ({projects.length})
                </span>
              )}
            </h2>
            <ProjectGrid projects={projects} onTagClick={() => {}} />
          </motion.div>
        )}

        {articles.length > 0 && (
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: 0.2 }}
          >
            <h2 className="text-2xl font-bold text-neutral-dark dark:text-white mb-8">
              Articles{' '}
              {articles.length > 0 && (
                <span className="text-lg font-normal text-neutral-dark/70 dark:text-white/70">
                  ({articles.length})
                </span>
              )}
            </h2>
            <ArticleGrid articles={articles} />
          </motion.div>
        )}

        {totalResults === 0 && (
          <motion.div
            initial={{ opacity: 0, scale: 0.95 }}
            animate={{ opacity: 1, scale: 1 }}
            className="text-center py-16 bg-white dark:bg-neutral-dark rounded-xl shadow-lg"
          >
            <p className="text-xl text-neutral-dark/70 dark:text-white/70 mb-6">
              No results found{' '}
              {tag ? (
                <span>
                  for{' '}
                  <span className="font-medium text-primary dark:text-primary-light">
                    &ldquo;{displayTag}&rdquo;
                  </span>
                </span>
              ) : (
                ''
              )}
            </p>
            {tag && (
              <Link
                to="/filtered"
                className="inline-flex items-center gap-2 px-6 py-3 bg-primary text-white rounded-full hover:bg-primary-dark transition-colors"
              >
                View all content
                <X className="w-4 h-4" />
              </Link>
            )}
          </motion.div>
        )}
      </div>
    </div>
  );
}
